import os
import re

def robust_process_ini_file(file_path):
    with open(file_path, 'rb') as f:
        original_bytes = f.read()

    bom = b''
    if original_bytes.startswith(b'\xef\xbb\xbf'):
        bom = b'\xef\xbb\xbf'

    content_bytes = original_bytes[len(bom):]
    text = content_bytes.decode('utf-8')
    lines = text.splitlines(keepends=True)

    new_lines = []
    in_target_section = False
    changed = False

    section_pattern = re.compile(r'^\[(.+)\]', re.IGNORECASE)
    port_pattern = re.compile(r'^(\s*port\s*=\s*)5432(\s*)$', re.IGNORECASE)

    for line in lines:
        section_match = section_pattern.match(line)
        if section_match:
            section_name = section_match.group(1).lower().strip()
            in_target_section = (section_name == 'veritabani')
            new_lines.append(line)
            continue

        if in_target_section:
            match = port_pattern.match(line)
            if match:
                prefix = match.group(1)
                suffix = match.group(2)
                new_line = prefix + "6543" + suffix
                new_lines.append(new_line)
                changed = True
                continue

        new_lines.append(line)

    if changed:
        new_content = bom + "".join(new_lines).encode('utf-8')
        with open(file_path, 'wb') as f:
            f.write(new_content)
        return True
    return False

def run_tests():
    test_dir = "test_env"
    if not os.path.exists(test_dir):
        os.makedirs(test_dir)

    test_files = {
        "1.ini": b"\xef\xbb\xbf[veritabani]\nport=5432\n[other]\nport=5432\n",
        "2.ini": b"[veritabani]\nport  =  5432\r\n[other]\nport=5432\r\n",
        "3.ini": b"[VERITABANI]\nport=5432\n",
        "4.ini": b"[veritabani]\n; port=5432\nport=5432\n",
        "5.ini": b"[veritabani]\nport=6543\n",
    }

    results = []

    for name, content in test_files.items():
        full_path = os.path.join(test_dir, name)
        with open(full_path, 'wb') as f:
            f.write(content)

        success = robust_process_ini_file(full_path)

        with open(full_path, 'rb') as f:
            final_content = f.read()

        if name == "1.ini":
            if b"\xef\xbb\xbf" in final_content and b"port=6543" in final_content and b"port=5432" in final_content:
                results.append(f"{name}: PASS")
            else:
                results.append(f"{name}: FAIL")
        elif name == "2.ini":
            if b"port  =  6543\r\n" in final_content:
                results.append(f"{name}: PASS")
            else:
                results.append(f"{name}: FAIL")
        elif name == "3.ini":
            if b"port=6543" in final_content:
                results.append(f"{name}: PASS")
            else:
                results.append(f"{name}: FAIL")
        elif name == "4.ini":
            if b"; port=5432" in final_content and b"port=6543" in final_content:
